begin;
alter table public.economic_regions add column country_code text not null default 'BR';
create table public.world_map_places(id bigint primary key,country_code text not null,region_code text references public.economic_regions(code),name text not null,latitude numeric not null check(latitude between -90 and 90),longitude numeric not null check(longitude between -180 and 180),is_capital boolean not null default false,is_port boolean not null default false);
alter table public.world_map_places enable row level security;
revoke all on public.world_map_places from public,anon,authenticated;
grant select on public.world_map_places to authenticated;
create policy world_places_read on public.world_map_places for select to authenticated using(true);
create index world_places_region on public.world_map_places(country_code,region_code);
create table public.infrastructure_project_types(code text primary key,name text not null,base_kind text not null,base_cost numeric not null,per_km numeric not null default 0,base_days integer not null,resource_code text references public.economic_resources(code),eligible_regions text[]);
alter table public.infrastructure_project_types enable row level security;
revoke all on public.infrastructure_project_types from public,anon,authenticated;
grant select on public.infrastructure_project_types to authenticated;
create policy world_project_types_read on public.infrastructure_project_types for select to authenticated using(true);
