create function private.world_region_route(p_start text,p_end text) returns text[] language plpgsql stable security definer set search_path='' as $$
declare queue jsonb:=jsonb_build_array(jsonb_build_array(p_start));path text[];visited text[]:='{}';neighbor text;cursor_code text;
begin
 while jsonb_array_length(queue)>0 loop
  select array_agg(value) into path from jsonb_array_elements_text(queue->0);queue:=queue-0;cursor_code:=path[array_length(path,1)];
  if cursor_code=p_end then return path;end if;if cursor_code=any(visited) then continue;end if;visited:=array_append(visited,cursor_code);
  for neighbor in select jsonb_array_elements_text(infrastructure_baseline->'map'->'neighbors') from public.economic_regions where public.economic_regions.code=cursor_code loop if not neighbor=any(visited) then queue:=queue||jsonb_build_array(to_jsonb(array_append(path,neighbor)));end if;end loop;
 end loop;raise exception 'Não há corredor terrestre cadastrado entre as regiões selecionadas.';
end $$;
revoke all on function private.world_region_route(text,text) from public,anon,authenticated;
create function public.quote_world_infrastructure(p_data jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare kind public.infrastructure_project_types%rowtype;origin public.world_map_places%rowtype;target public.world_map_places%rowtype;regions text[];coords jsonb:='[]';point jsonb;prev jsonb;km numeric:=0;cost numeric;days integer;category integer:=coalesce((p_data->>'category')::int,1);route_code text;gain numeric;
begin
 if auth.uid() is null then raise exception 'Entre para consultar o planejamento.' using errcode='42501';end if;
 select * into kind from public.infrastructure_project_types where code=p_data->>'kind';
 select * into origin from public.world_map_places where id=(p_data->>'origin_id')::bigint;
 if kind.code is null or origin.id is null or category not between 1 and 3 then raise exception 'Selecione tipo, cidade e categoria válidos.';end if;
 if kind.eligible_regions is not null and not origin.region_code=any(kind.eligible_regions) then raise exception 'Este recurso não está disponível no catálogo regional selecionado.';end if;
 if kind.code='ports' and not origin.is_port then raise exception 'Selecione uma cidade com referência portuária cadastrada.';end if;
 regions:=array[origin.region_code];coords:=jsonb_build_array(jsonb_build_array(origin.longitude,origin.latitude));
 if kind.code in('roads','railways') then
  select * into target from public.world_map_places where id=(p_data->>'target_id')::bigint;
  if target.id is null or target.id=origin.id or target.country_code<>origin.country_code then raise exception 'Selecione outro destino no mesmo país.';end if;
  regions:=private.world_region_route(origin.region_code,target.region_code);
  foreach route_code in array regions loop
   if route_code in(origin.region_code,target.region_code) then continue;end if;
   select jsonb_build_array((infrastructure_baseline->'map'->>'longitude')::numeric,(infrastructure_baseline->'map'->>'latitude')::numeric) into point from public.economic_regions r where r.code=route_code;coords:=coords||jsonb_build_array(point);
  end loop;
  coords:=coords||jsonb_build_array(jsonb_build_array(target.longitude,target.latitude));
  for point in select value from jsonb_array_elements(coords) loop
   if prev is not null then km:=km+6371*acos(greatest(-1,least(1,sin(radians((prev->>1)::numeric))*sin(radians((point->>1)::numeric))+cos(radians((prev->>1)::numeric))*cos(radians((point->>1)::numeric))*cos(radians((point->>0)::numeric-(prev->>0)::numeric)))));end if;prev:=point;
  end loop;
 end if;
 km:=round(km*1.12,1);cost:=round((kind.base_cost+kind.per_km*km)*(1+(category-1)*.5),2);days:=kind.base_days+ceil(km/50)::int+(category-1)*3;
 if cost>50000000 or days>90 then raise exception 'O corredor excede o limite da obra. Divida-o em trechos menores.';end if;
 gain:=least(20,cost/10000)/greatest(1,array_length(regions,1));
 return jsonb_build_object('kind',kind.code,'name',kind.name,'base_kind',kind.base_kind,'origin_id',origin.id,'target_id',target.id,'country_code',origin.country_code,'regions',regions,'coordinates',coords,'distance_km',km,'cost',cost,'days',days,'maintenance_weekly',round(cost*.01,2),'resource_code',kind.resource_code,'gain_per_region',gain,'category',category,'can_build',public.economic_has_role(array['Admin','Presidente','Ministro','Ministro da Fazenda','Ministro da Economia']),'geography_note','Corredor planejado do RP; distância de referência. Não representa uma estrada existente.');
end $$;
CREATE OR REPLACE FUNCTION public.propose_regional_infrastructure(p_region_code text, p_kind text, p_name text, p_budget numeric, p_duration_days integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare project uuid; region public.economic_regions%rowtype; sector uuid;
begin
 if auth.uid() is null or not public.economic_has_role(array['Admin','Presidente','Ministro','Ministro da Fazenda','Ministro da Economia']) then raise exception 'Seu cargo não permite propor obras públicas.' using errcode='42501';end if;
 select * into region from public.economic_regions where code=p_region_code;
 if region.code is null or p_kind is null or p_kind not in('roads','energy','ports','airports','telecom','industry','health') then raise exception 'Selecione um estado e uma infraestrutura disponíveis.';end if;
 if p_kind='ports' and not region.coastal and not exists(select 1 from public.world_map_places where region_code=region.code and is_port) then raise exception 'Este projeto exige uma referência portuária costeira ou fluvial cadastrada.';end if;
 if p_budget is null or p_budget<10000 or p_budget>50000000 or p_budget<>round(p_budget,2) or p_duration_days is null or p_duration_days not between 1 and 90 or length(trim(p_name)) not between 5 and 140 then raise exception 'Informe um nome de 5 a 140 caracteres, orçamento entre R$ 10 mil e R$ 50 milhões e prazo de 1 a 90 dias reais.';end if;
 select id into sector from public.economic_sectors where is_active order by case when name ilike '%saúde%' and p_kind='health' then 0 when name ilike '%constru%' then 1 else 2 end,code limit 1;
 project:=public.propose_government_project(trim(p_name),'Obra regional de '||region.name||'. Efeitos após conclusão; manutenção semanal de 1% do orçamento.',case when p_kind='health' then 'Saúde' else 'Infraestrutura' end,sector,case when p_kind='health' then 'health' else 'infrastructure' end,p_budget,public.real_date_to_rp_date(now()+make_interval(days=>p_duration_days)),0,0,0);
 update public.government_projects set region_code=p_region_code,infrastructure_kind=p_kind,construction_days=p_duration_days,infrastructure_gain=least(20,p_budget/10000),maintenance_weekly=round(p_budget*.01,2),healthcare_capacity=case when p_kind='health' then least(10000,floor(p_budget/100)) else 0 end where id=project;
 return project;
end $function$
;

create function public.create_world_infrastructure(p_data jsonb,p_idempotency_key uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare quote jsonb;project uuid;existing public.government_projects%rowtype;
begin
 if auth.uid() is null or not public.economic_has_role(array['Admin','Presidente','Ministro','Ministro da Fazenda','Ministro da Economia']) or public.is_admin_preview() then raise exception 'Seu acesso não permite iniciar obras governamentais.' using errcode='42501';end if;
 if p_idempotency_key is null or coalesce(length(btrim(p_data->>'name')),0) not between 5 and 140 then raise exception 'Informe o nome e a identificação da obra.';end if;
 perform pg_advisory_xact_lock(hashtextextended('world-project:'||p_idempotency_key,0));
 select * into existing from public.government_projects where metadata->>'world_map_key'=p_idempotency_key::text;
 if existing.id is not null then if existing.created_by<>auth.uid() or existing.metadata->'world_input' is distinct from p_data then raise exception 'A identificação já pertence a outro projeto.';end if;return existing.id;end if;
 quote:=public.quote_world_infrastructure(p_data);
 project:=public.propose_regional_infrastructure(quote->'regions'->>0,quote->>'base_kind',p_data->>'name',(quote->>'cost')::numeric,(quote->>'days')::int);
 update public.government_projects set infrastructure_gain=(quote->>'gain_per_region')::numeric,metadata=metadata||jsonb_build_object('world_map_key',p_idempotency_key,'world_input',p_data,'world_plan',quote,'route_regions',quote->'regions') where id=project;
 if public.economic_has_role(array['Admin','Presidente']) then perform public.approve_government_project(project,'Investimento confirmado no mapa mundial, conforme orçamento e competência.');end if;
 return project;
end $$;
create function public.get_world_map_state(p_country_code text default 'BR') returns jsonb language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 if auth.uid() is null then raise exception 'Entre para consultar o mapa.' using errcode='42501';end if;
 data:=public.get_regional_economy();
 return jsonb_build_object('server_now',clock_timestamp(),'regions',(select coalesce(jsonb_agg(value),'[]') from jsonb_array_elements(data->'regions') where value->>'country_code'=p_country_code),'projects',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.government_projects p join public.economic_regions r on r.code=p.region_code where p.infrastructure_kind is not null and r.country_code=p_country_code),'types',(select jsonb_agg(to_jsonb(t) order by name) from public.infrastructure_project_types t),'can_approve',public.economic_has_role(array['Admin','Presidente']),'can_build',public.economic_has_role(array['Admin','Presidente','Ministro','Ministro da Fazenda','Ministro da Economia']),'places',(select coalesce(jsonb_agg(to_jsonb(p) order by name),'[]') from public.world_map_places p where p.country_code=p_country_code));
end $$;
revoke all on function public.quote_world_infrastructure(jsonb),public.create_world_infrastructure(jsonb,uuid),public.get_world_map_state(text) from public,anon;
grant execute on function public.quote_world_infrastructure(jsonb),public.create_world_infrastructure(jsonb,uuid),public.get_world_map_state(text) to authenticated;

create or replace function private.refresh_regional_infrastructure() returns void language plpgsql security definer set search_path='' as $$begin
 update public.economic_regions r set roads=least(100,(r.infrastructure_baseline->>'roads')::numeric+coalesce(p.roads,0)),energy=least(100,(r.infrastructure_baseline->>'energy')::numeric+coalesce(p.energy,0)),ports=least(100,(r.infrastructure_baseline->>'ports')::numeric+coalesce(p.ports,0)),airports=least(100,(r.infrastructure_baseline->>'airports')::numeric+coalesce(p.airports,0)),telecom=least(100,(r.infrastructure_baseline->>'telecom')::numeric+coalesce(p.telecom,0)),industry=least(100,(r.infrastructure_baseline->>'industry')::numeric+coalesce(p.industry,0)),updated_at=now()
 from (select x.code,sum(g.infrastructure_gain) filter(where g.infrastructure_kind='roads') roads,sum(g.infrastructure_gain) filter(where g.infrastructure_kind='energy') energy,sum(g.infrastructure_gain) filter(where g.infrastructure_kind='ports') ports,sum(g.infrastructure_gain) filter(where g.infrastructure_kind='airports') airports,sum(g.infrastructure_gain) filter(where g.infrastructure_kind='telecom') telecom,sum(g.infrastructure_gain) filter(where g.infrastructure_kind='industry') industry from public.economic_regions x left join public.government_projects g on (g.region_code=x.code or coalesce(g.metadata->'route_regions','[]'::jsonb)?x.code) and g.status='completed' and g.regional_operational group by x.code) p where r.code=p.code;
end $$;
-- Keep the institutional panel on the same project rows and route metadata.
CREATE OR REPLACE FUNCTION public.get_regional_economy()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Entre para consultar o território.' using errcode='42501';end if;
 return jsonb_build_object('regions',(
  with company_stats as (
   select b.region_code,count(*) companies from public.businesses b where b.status='active' group by b.region_code
  ), employment as (
   select b.region_code,count(*) jobs,count(distinct e.profile_id) citizens from public.business_employees e join public.businesses b on b.id=e.business_id where e.fired_at is null group by b.region_code
  ), seeking as (
   select b.region_code,count(distinct a.profile_id) people from public.business_applications a join public.business_vacancies v on v.id=a.vacancy_id join public.businesses b on b.id=v.business_id where a.status='pending' and v.status='open' and not exists(select 1 from public.business_employees e where e.profile_id=a.profile_id and e.fired_at is null) group by b.region_code
  ), accounting as (
   select b.region_code,coalesce(sum(t.amount) filter(where t.type='revenue'),0) sales,coalesce(sum(t.amount) filter(where t.type='expense' and t.metadata->>'kind' in('input_consumption','overhead')),0) intermediate from public.business_transactions t join public.businesses b on b.id=t.business_id where t.accounting_date>=current_date-6 and t.accounting_date<=current_date group by b.region_code
  ), housing as (
   select r.code,count(h.id) homes from public.economic_regions r left join public.citizen_residences h on h.state in(r.code,r.name) group by r.code
  )
  select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('companies',coalesce(c.companies,0),'jobs',coalesce(e.jobs,0),'weekly_output',coalesce(a.sales,0),'weekly_gdp',coalesce(a.sales+a.intermediate,0),'registered_jobseekers',coalesce(s.people,0),'registered_workforce',coalesce(e.citizens,0)+coalesce(s.people,0),'registered_unemployment',round(100.0*coalesce(s.people,0)/nullif(coalesce(e.citizens,0)+coalesce(s.people,0),0),1),'housing',h.homes) order by r.name),'[]') from public.economic_regions r left join company_stats c on c.region_code=r.code left join employment e on e.region_code=r.code left join seeking s on s.region_code=r.code left join accounting a on a.region_code=r.code join housing h on h.code=r.code
 ),'projects',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'region_code',region_code,'kind',infrastructure_kind,'status',status,'progress',progress,'budget',approved_budget,'spent',spent_amount,'completion',expected_completion_at,'operational',regional_operational,'maintenance_weekly',maintenance_weekly,'capacity',healthcare_capacity,'metadata',metadata) order by created_at desc),'[]') from public.government_projects where infrastructure_kind is not null));
end $function$
;

